function canUseDetachedPromptPolling(run: SandboxRun): boolean {
  assert(run.id.length > 0, "detached prompt policy requires run id")
  assert(run.provider.length > 0, "detached prompt policy requires provider")
  return run.provider === "daytona" || run.provider === "e2b"
}

/**
 * Stable server-only identity for the published review session. The HMAC key is
 * never exposed to the source sandbox; only the isolated publisher receives the
 * derived value and canonicalizes the untrusted session metadata to it.
 */
async function reviewProvenanceSessionId(env: Env, run: SandboxRun): Promise<string> {
  if (!env.SESSION_SECRET) throw new Error("Review provenance session binding is not configured")
  if (!run.head_sha) throw new Error("Review provenance session binding requires an immutable HEAD")
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(env.SESSION_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  )
  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    encoder.encode(`review-provenance-v1:${run.id}:${run.head_sha}`),
  )
  const nonce = Array.from(new Uint8Array(signature).slice(0, 16), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("")
  return `review-${nonce}`
}

function shouldFinalizeReviewProvenance(run: SandboxRun): boolean {
  return (
    run.scope_type === "repo" &&
    Boolean(run.head_sha) &&
    run.output_config?.trailsReviewEnabled === true &&
    run.output_config.resultType === CODE_REVIEW_COMMENTS_RESULT_TYPE
  )
}

async function finalizeAcceptedReviewProvenance(
  env: Env,
  db: Db,
  run: SandboxRun,
): Promise<boolean> {
  if (!run.head_sha) throw new Error("Review provenance requires an immutable HEAD")
  const completed = await db.sandboxRuns.getRunById(run.id)
  if (completed?.status !== "succeeded") return false
  if (run.automation && run.trail_id) {
    const latest = await db.sandboxRuns.getLatestForTrail({
      automation: run.automation,
      trail_id: run.trail_id,
    })
    if (latest && latest.id !== run.id) return false
  }
  const result = await db.sandboxRuns.getAutomationResult(run.id, CODE_REVIEW_COMMENTS_RESULT_TYPE)
  if (!parseCodeReviewCommentsOutput(result?.data)) return false
  const sourceRepo = await getRunRepo(db, run)
  if (!sourceRepo?.app_has_access) throw new Error("Source repository is unavailable")
  const sourceToken = await mintRunnerToken(env, db, sourceRepo, {
    permissions: { contents: "read" },
  })
  const [settings, commitMessage] = await Promise.all([
    readEntireSettings(sourceRepo.full_name, run.head_sha, sourceToken),
    fetchCommitMessage(sourceRepo.full_name, run.head_sha, sourceToken),
  ])
  const { repo: commitCheckpointRepo } = resolveCheckpointRepo(sourceRepo.full_name, settings)
  // A reviewed PR can edit .entire/settings.json, so the immutable commit tells
  // us what the change proposes but cannot authorize a new write destination.
  // Continue against the persisted default-branch mapping instead of failing:
  // reviews of a legitimate settings change still need provenance, and the
  // source sandbox must never choose which repository receives write access.
  const checkpointRepoFullName =
    sourceRepo.checkpoint_repo_full_name?.trim() || sourceRepo.full_name
  if (commitCheckpointRepo.toLowerCase() !== checkpointRepoFullName.toLowerCase()) {
    console.warn("[sandbox-runs-queue] ignoring untrusted checkpoint repository override", {
      runId: run.id,
      reviewedCommitRepo: commitCheckpointRepo,
      authorizedRepo: checkpointRepoFullName,
    })
    recordSpanAttributes({ "runner.review_provenance.mapping_override": true })
    insertLifecycleEventSafely(db, {
      run_id: run.id,
      event_type: "review_provenance_checkpoint_mapping_override",
      payload: {
        reviewed_commit_repo: commitCheckpointRepo,
        authorized_repo: checkpointRepoFullName,
      },
    })
  }
  const checkpointRepo = await db.repos.getByFullName(checkpointRepoFullName)
  if (!checkpointRepo?.app_has_access) {
    throw new Error(`Checkpoint repository is unavailable: ${checkpointRepoFullName}`)
  }
  const checkpointIds = extractCheckpointIds(commitMessage)
  const expectedCheckpointId = checkpointIds.at(-1)
  if (!expectedCheckpointId) return false
  const checkpointToken = await mintRunnerToken(env, db, checkpointRepo, {
    permissions: { contents: "write" },
  })
  const expectedReviewSessionId = await reviewProvenanceSessionId(env, run)
  await finalizeReviewProvenance(env, db, {
    run,
    checkpointRepoFullName,
    checkpointToken,
    expectedCheckpointId,
    expectedReviewSessionId,
  })
  return true
}

async function ensureAcceptedReviewProvenance(
  env: Env,
  db: Db,
  run: SandboxRun,
  promptId: string,
): Promise<void> {
  const attached = await db.sandboxRuns.getLatestEventByType(run.id, "review_provenance_attached")
  if (attached) return
  if (!(await finalizeAcceptedReviewProvenance(env, db, run))) return
  await db.sandboxRuns.insertAppEvent({
    run_id: run.id,
    prompt_id: promptId,
    event_type: "review_provenance_attached",
    payload: { head_sha: run.head_sha },
  })
}

