/**
 * Base environment for a create-time sandbox (both providers), before any
 * per-command env from {@link commandRunnerEnv}. CLAUDE_CODE_SIMPLE is
 * deliberately never set: it runs claude in bare mode, which disables hook
 * auto-discovery and so suppresses the Entire checkpoint hooks. All agent CLI
 * API keys come from the registry.
 */
export function sandboxEnvVars(env: Env): Record<string, string> {
  const vars: Record<string, string> = { CI: "1" }
  const openai = getEnvVar(env, "OPENAI_API_KEY")
  if (openai) vars.OPENAI_API_KEY = openai
  return { ...vars, ...sandboxAgentApiKeyEnvVars(env) }
}

const PROMPT_ARG = `"$_entire_prompt"`

function readPromptArgFromFile(promptPath: string): string {
  return `_entire_prompt=$(cat ${shellQuote(promptPath)} && printf x) && _entire_prompt=\${_entire_prompt%x}`
}

export function commandRunnerEnv(env: Env, agent: string): Record<string, string> {
  const command = AGENT_COMMANDS[agent]
  if (!command) {
    throw new Error(`Unsupported command runner agent: ${agent}`)
  }

  const vars: Record<string, string> = { CI: "1" }
  if (command.requires_api_key && command.api_key_env_var) {
    const resolved = resolveAgentApiKeyEnvVar(env, command)
    if (!resolved) {
      const sourceName = command.api_key_source_env ?? command.api_key_env_var
      throw new Error(`Agent "${agent}" requires ${sourceName} to be configured`)
    }
    vars[resolved.name] = resolved.value
    // Postcondition: a key-requiring agent leaves here with its CLI key set, so
    // the sandbox can authenticate.
    assert(vars[command.api_key_env_var] === resolved.value, "agent api key must be set in env")
  }
  return vars
}

export function buildAgentCommand(
  agent: string,
  model: string | null,
  systemPrompt: string | null,
  promptPath: string,
  extraArgs: string[] = [],
): string {
  // The prompt is delivered via this path (stdin redirect or a shell read), so
  // an empty path would silently feed the agent nothing.
  assert(promptPath.length > 0, "buildAgentCommand requires a prompt path")

  const command = AGENT_COMMANDS[agent]
  if (!command) {
    throw new Error(`Unsupported command runner agent: ${agent}`)
  }

  const args = [...command.args]
  if (model && command.model_flag) {
    args.push(command.model_flag, model)
  }
  if (systemPrompt) {
    // Fail loud rather than silently drop a required system prompt: an agent with
    // no way to apply it (codex, cursor) would otherwise run without its
    // instructions and emit malformed output with a zero exit.
    if (!command.system_prompt_flag) {
      throw new Error(`Agent "${agent}" cannot apply a system prompt`)
    }
    args.push(command.system_prompt_flag, systemPrompt)
  }
  args.push(...extraArgs)
  if (command.prompt_flag) {
    args.push(command.prompt_flag, PROMPT_ARG)
    const built = `${readPromptArgFromFile(promptPath)} && ${[command.command, ...args]
      .map((arg) => (arg === PROMPT_ARG ? arg : shellQuote(arg)))
      .join(" ")}`
    // The prompt-flag form must reference the read prompt arg, else the flag is
    // passed with no content.
    assert(built.includes(PROMPT_ARG), "prompt-flag command must carry the prompt arg")
    return built
  }

  const built = `${[command.command, ...args].map(shellQuote).join(" ")} < ${shellQuote(promptPath)}`
  // Stdin form: the command must end by redirecting the prompt file into the
  // agent, which is how codex/claude receive the prompt.
  assert(built.includes(`< ${shellQuote(promptPath)}`), "stdin command must redirect the prompt")
  return built
}

