async finalizeReviewProvenance(
  env: Env,
  _db: Db,
  {
    run,
    checkpointRepoFullName,
    checkpointToken,
    expectedCheckpointId,
    expectedReviewSessionId,
  }: FinalizeReviewProvenanceParams,
): Promise<void> {
  const config = getDaytonaProviderConfig(env)
  if (!config || !env.DAYTONA_API_KEY || !run.environment_id || !run.head_sha) {
    throw new Error("Review provenance finalizer is not configured")
  }
  const client = createClient(env)
  const source = await client.get(run.environment_id)
  await runCommand(
    source,
    entireAttachReviewCommand(run.agent, REPO_DIR, run.head_sha),
    commandOptions(120_000),
  )
  const bundle = await source.fs.downloadFile(REVIEW_PROVENANCE_BUNDLE_PATH)
  if (bundle.byteLength === 0 || bundle.byteLength > MAX_REVIEW_PROVENANCE_BUNDLE_BYTES) {
    throw new Error(`Review provenance bundle has invalid size: ${bundle.byteLength}`)
  }
  const publisher = await client.create(
    {
      image: config.baseSnapshot,
      envVars: { CI: "1" },
      autoStopInterval: 10,
      autoDeleteInterval: DAYTONA_AUTO_DELETE_INTERVAL_MINUTES,
      public: false,
      labels: { "entire-run-id": run.id, "entire-service": "review-provenance-publisher" },
      resources: DAYTONA_RESOURCES,
      ...resolveDaytonaNetworkOptions(config),
    },
    { timeout: PROVISION_TIMEOUT_SECONDS },
  )
  try {
    await prepareNodeToolingIfNeeded(publisher)
    await publisher.fs.uploadFile(bundle, REVIEW_PROVENANCE_BUNDLE_PATH)
    await configureGitAuth(publisher, checkpointToken)
    await runCommand(
      publisher,
      entirePublishReviewBundleCommand(
        `https://github.com/${checkpointRepoFullName}.git`,
        expectedCheckpointId,
        expectedReviewSessionId,
        GIT_ASKPASS,
      ),
      commandOptions(240_000),
    )
  } finally {
    await publisher.delete().catch(() => undefined)
  }
}

