function commandOptions(
  timeout: number,
  opts: Omit<CommandOptions, "timeoutMs"> = {},
): CommandOptions {
  return {
    ...opts,
    timeoutMs: timeout,
    requestTimeoutMs: opts.requestTimeoutMs ?? Math.max(60_000, timeout),
  }
}

async function runCommand(
  sandbox: Pick<E2bSandbox, "commands">,
  command: string,
  opts: CommandOptions = {},
): Promise<string> {
  const result = await sandbox.commands.run(command, opts)
  if ("exitCode" in result && result.exitCode !== 0) {
    throw new Error(
      `Command failed (exit ${result.exitCode}): ${command}\n${result.stderr || result.stdout || ""}`,
    )
  }
  return "stdout" in result ? (result.stdout ?? "") : ""
}

function detachedPromptPaths(runId: string, promptId: string): DetachedPromptPaths {
  assert(runId.length > 0, "detachedPromptPaths requires runId")
  assert(promptId.length > 0, "detachedPromptPaths requires promptId")
  const base = `${DETACHED_PROMPT_DIR}/${runId}/${promptId}`
  return {
    logPath: `${base}.ndjson`,
    stderrPath: `${base}.stderr`,
    exitCodePath: `${base}.exit`,
    pidPath: `${base}.pid`,
  }
}

function e2bDetachedSessionRecord(value: unknown): E2bDetachedSessionRecord | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null
  const record = value as Record<string, unknown>
  if (typeof record.pid !== "number" || !Number.isSafeInteger(record.pid)) return null
  if (record.pid <= 0) return null
  if (typeof record.logPath !== "string" || !record.logPath.startsWith("/")) return null
  if (typeof record.exitCodePath !== "string" || !record.exitCodePath.startsWith("/")) return null
  if (typeof record.pidPath !== "string" || !record.pidPath.startsWith("/")) return null
  const stderrPath =
    typeof record.stderrPath === "string" ? record.stderrPath : `${record.logPath}.stderr`
  if (typeof record.promptId !== "string" || record.promptId.length === 0) return null
  return {
    promptId: record.promptId,
    pid: record.pid,
    logPath: record.logPath,
    stderrPath,
    exitCodePath: record.exitCodePath,
    pidPath: record.pidPath,
  }
}

