// Structured extraction + classification of sandbox-run failures.
//
// Provider command failures arrive in two shapes:
//   - e2b: the SDK throws `CommandExitError`, which exposes `exitCode`/`stderr`
//     getters but stringifies to a bare "exit status 128".
//   - daytona / our own `runCommand`: a plain Error whose message embeds the
//     exit code and stderr ("Command failed (exit 128): <cmd>\n<stderr>").
//
// Both lose their useful signal once flattened through `errorString()`. These
// helpers recover `{ exitCode, stderr }` from either shape so we can persist it,
// put it on the span, and (later) drive per-class retry decisions.

/** Low-cardinality failure buckets — safe to use as a Honeycomb breakdown. */
export type ProvisionFailureClass =
  | "transient_network"
  | "deleted_ref"
  | "auth"
  | "timeout"
  | "unknown"

export interface CommandFailure {
  /** Process exit code when known; null if it could not be determined. */
  exitCode: number | null
  /** Combined stderr (falling back to stdout / message) for diagnosis. */
  stderr: string
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return typeof value === "object" && value !== null ? (value as Record<string, unknown>) : null
}

/**
 * Recover `{ exitCode, stderr }` from an unknown thrown value, handling the e2b
 * `CommandExitError` (structured getters) and the embedded-message format used
 * by daytona / our own `runCommand`.
 */
export function extractCommandFailure(error: unknown): CommandFailure {
  const record = asRecord(error)

  // e2b CommandExitError (and our shaped command results): structured fields.
  if (record && typeof record.exitCode === "number") {
    const stderr =
      typeof record.stderr === "string" && record.stderr.length > 0
        ? record.stderr
        : typeof record.stdout === "string"
          ? record.stdout
          : ""
    return { exitCode: record.exitCode, stderr }
  }

  const message = error instanceof Error ? error.message : typeof error === "string" ? error : ""

  // Embedded format: "Command failed (exit 128): <cmd>\n<stderr...>"
  const exitMatch = message.match(/exit(?: status)? (\d+)/i)
  const exitCode = exitMatch ? Number(exitMatch[1]) : null
  const newlineIndex = message.indexOf("\n")
  const stderr = newlineIndex >= 0 ? message.slice(newlineIndex + 1).trim() : message

  return { exitCode, stderr }
}

/**
 * A stable, low-cardinality fingerprint of a stderr blob: the first meaningful
 * line, lower-cased, with high-cardinality bits (SHAs, URLs, quoted paths)
 * masked and the result truncated. Suitable as a Honeycomb breakdown.
 */
export function stderrSignature(stderr: string): string {
  const firstLine =
    stderr
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line.length > 0) ?? ""

  return firstLine
    .toLowerCase()
    .replace(/'[^']*'/g, "<arg>")
    .replace(/"[^"]*"/g, "<arg>")
    .replace(/https?:\/\/\S+/g, "<url>")
    .replace(/\b[0-9a-f]{7,40}\b/g, "<sha>")
    .slice(0, 120)
}

/**
 * Low-cardinality span attributes describing a provision failure, for BubbleUp.
 * `provision.exit_code` is -1 when the code could not be determined.
 */
export function provisionFailureAttributes(error: unknown): Record<string, string | number> {
  const failure = extractCommandFailure(error)
  return {
    "provision.exit_code": failure.exitCode ?? -1,
    "provision.failure_class": classifyProvisionFailure(failure),
    "provision.stderr_signature": stderrSignature(failure.stderr),
  }
}

/**
 * A persistence-friendly failure message that includes the recovered stderr, so
 * the stored `error_message` is diagnosable instead of a bare "exit status 128".
 */
export function enrichFailureMessage(error: unknown): string {
  const base = error instanceof Error ? error.message : String(error)
  const { stderr } = extractCommandFailure(error)
  if (!stderr || base.includes(stderr)) return base.slice(0, 1000)
  return `${base}: ${stderr}`.slice(0, 1000)
}

const NETWORK_PATTERNS =
  /could not resolve host|couldn't resolve host|failed to connect|connection timed out|connection reset|network connection lost|unable to access|could not read from remote|tls|ssl|gnutls|error: 50\d|the requested url returned error: 5/i
const DELETED_REF_PATTERNS =
  /couldn'?t find remote ref|did not match any|unknown revision|pathspec .* did not match|remote ref .* not found|reference is not a tree/i
const AUTH_PATTERNS =
  /could not read username|authentication failed|terminal prompts disabled|403 forbidden|permission denied|fatal: could not read|invalid username or password|repository not found/i

/**
 * Map a command failure to a low-cardinality class for telemetry. Observability
 * only — deliberately decoupled from retry policy (which keys off the run phase,
 * not the error class). Ambiguous failures fall through to "unknown".
 */
export function classifyProvisionFailure(failure: CommandFailure): ProvisionFailureClass {
  // 124 is the exit code our command runner assigns on deadline/timeout.
  if (failure.exitCode === 124) return "timeout"

  const haystack = failure.stderr
  if (DELETED_REF_PATTERNS.test(haystack)) return "deleted_ref"
  if (AUTH_PATTERNS.test(haystack)) return "auth"
  if (NETWORK_PATTERNS.test(haystack)) return "transient_network"

  return "unknown"
}

