    // surface the no-session contract string instead of a node stacktrace.
    expect(command).toContain(
      'entire session current --json > \'/tmp/entire-review-session.json\' || { echo "review provenance could not resolve the current Entire session" >&2; exit 1; }',
    )
    // Non-JSON file contents (older CLI prints a plain-text hint with exit 0)
    // must yield an empty field, not a JSON.parse crash.
    expect(command).toContain("try{v=JSON.parse")
    expect(command).toContain('review provenance attach failed for session $session_id')
  })
})

describe("reviewProvenanceFailureReason", () => {
  it("classifies the attach script's contract strings", () => {
    const cases: Array<[string, string]> = [
      ["review provenance HEAD mismatch: expected a, got b", "head_mismatch"],
      ["review provenance requires an existing Entire-Checkpoint trailer", "missing_trailer"],
      ["review provenance could not resolve the current Entire session", "no_session"],
      ["No active session found in this worktree.", "no_session"],
      [
        "session abc already has checkpoint 795233682e33; rewriting an existing checkpoint as a review is not supported yet",
        "attach_rejected",
      ],
      ["review provenance attach failed for session abc", "attach_rejected"],
      ["review provenance changed HEAD unexpectedly", "head_moved"],
      ["review provenance changed the checkpoint trailer unexpectedly", "trailer_changed"],
      ["Review provenance bundle has invalid size: 0", "invalid_bundle"],
      ["command timed out after 120000ms", "timeout"],
      ["some novel failure", "unknown"],
    ]
    for (const [message, expected] of cases) {
      expect(reviewProvenanceFailureReason(new Error(message))).toBe(expected)
    }
  })

  it("reads structured stderr from e2b-style errors that stringify to 'exit status 1'", () => {
    const error = Object.assign(new Error("exit status 1"), {
      exitCode: 1,
      stderr: "review provenance requires an existing Entire-Checkpoint trailer\n",
      stdout: "",
    })
    expect(reviewProvenanceFailureReason(error)).toBe("missing_trailer")
  })

  it("reads stdout when the marker only appears there", () => {
    const error = Object.assign(new Error("exit status 1"), {
      exitCode: 1,
      stderr: "",
      stdout: "No active session found in this worktree.\n",
    })
    expect(reviewProvenanceFailureReason(error)).toBe("no_session")
  })
})

