async finalizeReviewProvenance(
  env: Env,
  _db: Db,
  {
    run,
    checkpointRepoFullName,
    checkpointToken,
    expectedCheckpointId,
    expectedReviewSessionId,
  }: FinalizeReviewProvenanceParams,
): Promise<void> {
  const config = getE2bProviderConfig(env, undefined, run.agent)
  if (!config || !env.E2B_API_KEY || !run.environment_id || !run.head_sha) {
    throw new Error("Review provenance finalizer is not configured")
  }
  const source = toE2bSandbox(
    await Sandbox.connect(run.environment_id, { apiKey: env.E2B_API_KEY }),
  )
  await runCommand(
    source,
    entireAttachReviewCommand(run.agent, REPO_DIR, run.head_sha, expectedCheckpointId),
    commandOptions(120_000),
  )
