// Deliberately does NOT run `entire enable`: sandboxes never install Entire
// hooks. Hook-tracked runner sessions caused more harm than good (the
// session-stop hook checkpointed reviewer sessions into conflict with the
// platform attach, codex hooks require per-user trust sandboxes lack, and the
// pre-push checkpoint sync cannot traverse the single-ref brokered-push
// proxy). Provenance is attached platform-side from the agent's on-disk
// transcript instead; only the prefetched checkpoint base is needed as the
// graft/bundle parent.
async function prefetchEntireCheckpointBase(
  sandbox: DaytonaSandbox,
  trace: ProvisionStepTracer = noopProvisionStepTracer,
): Promise<void> {
  await trace("entire_checkpoint_prefetch", () =>
    runCommand(
      sandbox,
      entireCheckpointPrefetchCommand(REPO_DIR, GIT_ASKPASS),
      commandOptions(120_000),
    ),
  )
}

